using System.Text.Json;
using System.Text.Json.Serialization;
using System.Text.Json.Serialization.Metadata;

// --- 1. GetTypeInfo<T>(): strongly-typed metadata retrieval ---

// Web defaults include the default reflection-based resolver,
// so metadata for any serializable type is available.
var options = new JsonSerializerOptions(JsonSerializerDefaults.Web);

JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"GetTypeInfo<Person>() => Type={personInfo.Type.Name}, Kind={personInfo.Kind}");

string json = JsonSerializer.Serialize(new Person("Ada", 36), personInfo);
Console.WriteLine($"Serialized: {json}");

// --- 2. TryGetTypeInfo<T>(): probe without throwing ---

// Same options – Person is resolvable, so this returns true.
if (options.TryGetTypeInfo<Person>(out var info))
{
    Console.WriteLine($"TryGetTypeInfo<Person>() => true, Type={info!.Type.Name}");
}

// Now use options with a custom resolver that only knows about Person.
// Asking for int[] will return false instead of throwing.
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver
    {
        Modifiers =
        {
            ti =>
            {
                if (ti.Type != typeof(Person))
                    throw new NotSupportedException($"Type {ti.Type} not supported");
            }
        }
    }
};

if (limited.TryGetTypeInfo<int[]>(out var arrayInfo))
{
    Console.WriteLine($"TryGetTypeInfo<int[]>() => true (unexpected)");
}
else
{
    Console.WriteLine("TryGetTypeInfo<int[]>() => false — metadata not available, no exception thrown");
}

public record Person(string Name, int Age);

